mapper.select:
SELECT B.BOOKSET_ID BOOKSETID, FIN.FINPROD_NAME FINPRODNAME, FIN.FINPROD_NAME FINPRODNAMEABBR, '理财产品' FINPRODTYPE, DATE_FORMAT(B.VAL_DATE,'%Y-%m-%d') AS HAPPENDATE, B.MARKET_VALUE/100000000 NETAMT FROM BOK_VAL_TABLE_DATA B LEFT JOIN FIN_PRODUCT FIN ON FIN.FINPROD_ID = B.BOOKSET_ID and FIN.FINPROD_TYPE='F16' WHERE 1 = 1 AND B.SUBJECT_NO = '产品资产净值：'
AND B.VAL_DATE >= #{happenDateBegin}
AND B.VAL_DATE <= #{happenDateEnd}
AND B.BOOKSET_ID in
#{item}
ORDER BY B.VAL_DATE DESC
